package app.streamnest;
import java.util.*;import java.net.URI;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import org.json.*;
/** IMDb-scoped trailer metadata and YouTube availability. Never extracts media streams. */
final class Trailers {
 static final ThreadPoolExecutor worker=new ThreadPoolExecutor(0,1,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8));
 interface Fetcher{JSONObject get(String url,long deadline)throws Exception;}
 static Fetcher fetcher=(url,deadline)->new JSONObject(new String(Net.catalogBytes(url,2000000,deadline),StandardCharsets.UTF_8));
 static final class Result{final String id,url,title;Result(String id,String title){this.id=id;this.url=Trailers.url(id);this.title=title;}}
 static final class Entry{final Result result;final long expires;Entry(Result r,long expires){result=r;this.expires=expires;}}
 static final Map<String,Entry> cache=new LinkedHashMap<>();
 static String videoId(String value){if(value==null)return "";if(value.matches("[A-Za-z0-9_-]{11}"))return value;try{URI u=URI.create(value);if(!"https".equals(u.getScheme())||u.getUserInfo()!=null)return "";String host=u.getHost(),id="";if("youtu.be".equals(host))id=u.getPath().substring(1);else if(Arrays.asList("youtube.com","www.youtube.com","m.youtube.com").contains(host)){if("/watch".equals(u.getPath())){for(String pair:Objects.toString(u.getRawQuery(),"").split("&"))if(pair.startsWith("v="))id=pair.substring(2);}else if(u.getPath().matches("/(embed|shorts)/[A-Za-z0-9_-]{11}"))id=u.getPath().substring(u.getPath().lastIndexOf('/')+1);}return id.matches("[A-Za-z0-9_-]{11}")?id:"";}catch(Exception e){return "";}}
 static String url(String value){String id=videoId(value);return id.isEmpty()?"":"https://www.youtube.com/watch?v="+id;}
 static List<String> candidates(JSONObject meta,String id){List<String> out=new ArrayList<>();if(meta==null||!id.matches("tt[0-9]+")||!id.equals(meta.optString("imdb_id",meta.optString("id"))))return out;JSONArray rows=meta.optJSONArray("trailers");if(rows!=null)for(int n=0;n<rows.length();n++){JSONObject r=rows.optJSONObject(n);if(r!=null&&r.optString("type").equalsIgnoreCase("Trailer")){String yt=videoId(r.optString("source"));if(!yt.isEmpty()&&!out.contains(yt))out.add(yt);}}rows=meta.optJSONArray("trailerStreams");if(rows!=null)for(int n=0;n<rows.length();n++){JSONObject r=rows.optJSONObject(n);String yt=videoId(r==null?"":r.optString("ytId"));if(!yt.isEmpty()&&!out.contains(yt))out.add(yt);}return out.subList(0,Math.min(4,out.size()));}
 static Result resolve(Catalog.Title title)throws Exception{String key=title.kind+":"+title.id;long now=System.currentTimeMillis();if(!title.id.matches("tt[0-9]+"))return null;synchronized(cache){Entry old=cache.get(key);if(old!=null&&now<old.expires)return old.result;}long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);JSONObject doc=fetcher.get("https://v3-cinemeta.strem.io/meta/"+(title.kind.equals("movies")?"movie":"series")+"/"+title.id+".json",deadline);List<String> ids=candidates(doc.optJSONObject("meta"),title.id);Result result=null;boolean failed=false;for(String id:ids.subList(0,Math.min(3,ids.size()))){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(System.nanoTime()>=deadline)break;try{JSONObject data=fetcher.get("https://www.youtube.com/oembed?url="+URLEncoder.encode(url(id),"UTF-8")+"&format=json",deadline);if(data.optString("provider_name").equals("YouTube")&&!data.optString("title").trim().isEmpty()){result=new Result(id,data.getString("title").substring(0,Math.min(200,data.getString("title").length())));break;}}catch(Exception e){failed=true;}}if(!failed||result!=null)synchronized(cache){cache.put(key,new Entry(result,now+(result==null?1800000:86400000)));while(cache.size()>128)cache.remove(cache.keySet().iterator().next());}return result;}
}
